package com.komainos.mantenimiento.dto;
import com.komainos.mantenimiento.model.*;import com.komainos.mantenimiento.service.ServicioConsultaAutomatizacion.FichaAutomatizacion;import com.komainos.inventario.model.NivelAlerta;import java.util.*;import java.time.Instant;import java.math.BigDecimal;
public record AutomatizacionOrdenRespuesta(Integer idOrden,boolean simulado,List<Plan> mops,List<Analisis> evaluaciones,List<Solicitud> autorizaciones,List<Validacion> validaciones,List<ValidacionTecnicaVista> validacionesTecnicas,List<Problema> incidencias,OrdenResumenRespuesta orden,List<OrdenDetalleRespuesta.CambioEstado> historial){
 public static AutomatizacionOrdenRespuesta de(FichaAutomatizacion f){return new AutomatizacionOrdenRespuesta(f.orden().getId(),f.simulado(),f.mops().stream().map(m->Plan.de(m,f.maxDuracionMop())).toList(),f.evaluaciones().stream().map(Analisis::de).toList(),f.autorizaciones().stream().map(Solicitud::de).toList(),f.validaciones().stream().map(v->new Validacion(v.getId(),v.getResponsable().getId(),v.getResponsable().getNombreCompleto(),v.getEstado(),v.getFechaLimite(),v.getFechaRespuesta(),v.getObservaciones())).toList(),f.validacionesTecnicas().stream().map(v->new ValidacionTecnicaVista(v.getDetalle().getId(),v.getResultado(),v.getObservaciones(),v.getFechaValidacion())).toList(),f.incidencias().stream().map(Problema::de).toList(),com.komainos.mantenimiento.mapper.OrdenMapeador.resumen(f.orden()),f.orden().getHistorial().stream().map(h->new OrdenDetalleRespuesta.CambioEstado(h.getEstadoAnterior(),h.getEstadoNuevo(),h.getMotivo(),h.getUsuario()==null?null:new com.komainos.shared.dto.ReferenciaSimple(h.getUsuario().getId(),h.getUsuario().getNombreCompleto()),h.getFechaHora())).toList());}
 public record Plan(Integer id,Integer idDetalle,String servidor,int duracionMinutos,boolean piloto,boolean superaDuracionMaxima,List<TareaMop> tareas){static Plan de(Mop m,int maximo){return new Plan(m.getId(),m.getDetalle().getId(),m.getDetalle().getServidor().getHostname(),m.duracionTotal(),m.getDetalle().isEsServidorPiloto(),m.duracionTotal()>maximo,m.getTareas().stream().map(TareaMop::de).toList());}}
 public record TareaMop(Integer id,Integer idTarea,String tarea,int prioridad,int duracionMinutos,String afectacion,Integer idVersion,Integer numeroVersion,Integer idCuentaServicio,EstadoTareaMop estado,Integer codigoRetorno,String salida,String error,Instant fechaInicio,Instant fechaFin){static TareaMop de(MopTarea t){return new TareaMop(t.getId(),t.getTarea().getId(),t.getTarea().getNombre(),t.getPrioridadAplicada(),t.getDuracionEstimadaMinutos(),t.getNivelAfectacion().name(),t.getVersion()==null?null:t.getVersion().getId(),t.getVersion()==null?null:t.getVersion().getNumeroVersion(),t.getIdCuentaServicio(),t.getEstado(),t.getCodigoRetorno(),t.getSalida(),t.getError(),t.getFechaInicio(),t.getFechaFin());}}
 public record Analisis(Integer id,Integer idDetalle,Integer idServidor,String servidor,TipoEvaluacion tipo,EstadoEvaluacion estado,Integer idVersion,Integer idCuentaServicio,Instant fechaInicio,Instant fechaFin,String error,List<Medicion> mediciones){public static Analisis de(Evaluacion e){return new Analisis(e.getId(),e.getDetalle()==null?null:e.getDetalle().getId(),e.getServidor().getId(),e.getServidor().getHostname(),e.getTipo(),e.getEstado(),e.getVersion().getId(),e.getIdCuentaServicio(),e.getFechaInicio(),e.getFechaFin(),e.getError(),e.getMediciones().stream().map(m->new Medicion(m.getMetrica().getCodigo(),m.getMetrica().getNombre(),m.getInstancia(),m.getValor(),List.copyOf(m.getElementos()),m.getUmbrales().stream().map(u->new UmbralEvaluado(u.getIdUmbral(),u.getIdExcepcion(),u.getNivel(),u.getAdvertencia(),u.getCritico(),u.getOperador()==null?null:u.getOperador().name(),u.getIdLista(),u.getNivelFaltante(),u.getNivelSobrante(),u.getFechaEvaluacion())).toList())).toList());}}
 public record Medicion(String codigo,String nombre,String instancia,BigDecimal valor,List<String> elementos,List<UmbralEvaluado> umbrales){}
 public record UmbralEvaluado(Integer idUmbral,Integer idExcepcion,NivelAlerta nivel,BigDecimal advertencia,BigDecimal critico,String operador,Integer idLista,NivelAlerta nivelFaltante,NivelAlerta nivelSobrante,Instant fechaEvaluacion){}
 public record Solicitud(Integer id,int ronda,Instant fechaLimite,String entorno,String afectacion,List<Decision> decisiones){static Solicitud de(SolicitudAutorizacion s){return new Solicitud(s.getId(),s.getNumeroRonda(),s.getFechaLimite(),s.getRegla().getEntorno().getNombre(),s.getRegla().getAfectacion().name(),s.getDecisiones().stream().map(a->new Decision(a.getId(),a.getTipo(),a.getOrdenSecuencia(),a.getEstado(),a.getUsuarioDecision()==null?null:a.getUsuarioDecision().getNombreCompleto(),a.getFechaSolicitud(),a.getFechaDecision(),a.getFechaPropuesta(),a.getMotivo())).toList());}}
 public record Decision(Integer id,TipoAprobador tipo,int secuencia,EstadoAutorizacion estado,String usuario,Instant fechaSolicitud,Instant fechaDecision,Instant fechaPropuesta,String motivo){}
 public record ValidacionTecnicaVista(Integer idDetalle,ResultadoValidacionTecnica resultado,String observaciones,Instant fecha){}
 public record Validacion(Integer id,Integer idResponsable,String responsable,EstadoValidacionFuncional estado,Instant fechaLimite,Instant fechaRespuesta,String observaciones){}
 public record Problema(Integer id,Integer idOrden,Integer idServidor,String orden,String servidor,OrigenIncidencia origen,EstadoIncidencia estado,String error,String diagnostico,String acciones,String resultado,Instant fechaApertura,Instant fechaCierre){public static Problema de(Incidencia i){return new Problema(i.getId(),i.getDetalle().getOrden().getId(),i.getDetalle().getServidor().getId(),i.getDetalle().getOrden().getCodigo(),i.getDetalle().getServidor().getHostname(),i.getOrigen(),i.getEstado(),i.getError(),i.getDiagnostico(),i.getAccionesRealizadas(),i.getResultado(),i.getFechaApertura(),i.getFechaCierre());}}
}
